mapper.select:
SELECT u.id, u.dept_id, u.username, u.nickname, u.email, u.phone, u.gender,
       u.avatar, u.status, u.login_ip, u.login_date, u.login_count, u.login_fail_count, u.pwd_reset_time,
       u.create_by, u.create_time, u.update_by, u.update_time, u.del_flag, u.remark,
       d.dept_name AS "dept.deptName"
FROM sys_user u
LEFT JOIN sys_dept d ON u.dept_id = d.id AND d.del_flag = 0
WHERE u.del_flag = 0


    AND u.username LIKE CONCAT('%', #{escapedUsername}, '%') ESCAPE '\\'



    AND u.nickname LIKE CONCAT('%', #{escapedNickname}, '%') ESCAPE '\\'



    AND u.phone LIKE CONCAT('%', #{escapedPhone}, '%') ESCAPE '\\'


    AND u.status = #{query.status}


    AND u.dept_id = #{query.deptId}


    AND u.dept_id IN

        #{deptId}



    AND u.create_time >= #{query.beginTime}


    AND u.create_time <= #{query.endTime}

${query.params.dataScope}
ORDER BY u.create_time DESC
